//! The `ErrorInfo` trait, the code catalog (`CodeInfo`, `CodeState`,
//! `UrlDisplay`), and `catalog::find` / `catalog::check_unique`.

use core::{fmt, time::Duration};

use crate::{Action, Category, Code, Kinds, Location, Severity};

/// The metadata of an error, read the same way for every error type.
///
/// Every type generated by `define_errors!` implements it. A hand-written error
/// type can implement it with `impl ErrorInfo for MyError {}` and override what
/// it needs: every method has a default, and the defaults follow the category.
/// The trait is object safe, so `&dyn ErrorInfo` works. No method allocates or
/// locks.
///
/// # Examples
///
/// ```
/// use define_err::prelude::*;
///
/// define_errors! {
///     namespace = "DB";
///
///     pub enum DbError {
///         #[code(1, help = "Raise pool.size or lower the load.")]
///         #[category(DeadlineExceeded)]
///         #[public("The database is busy. Try again shortly.")]
///         Timeout { after_ms: u64 } => "query timed out after {after_ms} ms",
///     }
/// }
///
/// fn respond(err: &dyn ErrorInfo) -> (u16, &'static str) {
///     (err.category().http_status(), err.public_message())
/// }
///
/// let err = DbError::Timeout { after_ms: 5000 };
/// assert_eq!(respond(&err), (504, "The database is busy. Try again shortly."));
/// assert_eq!(err.code().unwrap().to_string(), "DB-0001");
/// ```
pub trait ErrorInfo: core::error::Error {
    /// The stable code, if the variant has one.
    #[inline]
    fn code(&self) -> Option<Code> {
        None
    }

    /// The catalog entry of the code: title, help, docs URL, state.
    #[inline]
    fn code_info(&self) -> Option<&'static CodeInfo> {
        None
    }

    /// The category: HTTP status, gRPC code, exit code, retry rule.
    /// `Category::Unknown` by default.
    #[inline]
    fn category(&self) -> Category {
        Category::Unknown
    }

    /// The severity; the category's default unless the variant says.
    #[inline]
    fn severity(&self) -> Severity {
        self.category().default_severity()
    }

    /// The kinds, for filters. `Kinds::ERROR` by default.
    #[inline]
    fn kinds(&self) -> Kinds {
        Kinds::ERROR
    }

    /// Text a client may see. Never derived from `Display`: the category's
    /// default text unless the variant writes its own.
    #[inline]
    fn public_message(&self) -> &'static str {
        self.category().default_public_message()
    }

    /// What to do about the error, from the code's `help`.
    #[inline]
    fn help(&self) -> Option<&'static str> {
        None
    }

    /// Who acts on the error; the category's default unless the variant says.
    #[inline]
    fn action(&self) -> Action {
        self.category().default_action()
    }

    /// Whether the condition may clear on its own. Only idempotent operations
    /// may retry automatically ([`Category::may_retry_automatically`]).
    #[inline]
    fn is_retryable(&self) -> bool {
        self.category().is_transient()
    }

    /// How long to wait before a retry, when known.
    #[inline]
    fn retry_after(&self) -> Option<Duration> {
        None
    }

    /// Where the error was built or converted, when the variant records it in
    /// a `#[location]` field.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::prelude::*;
    ///
    /// define_errors! {
    ///     pub enum StoreError {
    ///         Full { #[location] at: Location } => "the store is full",
    ///     }
    /// }
    ///
    /// let err = StoreError::Full { at: define_err::here() };
    /// assert_eq!(err.location().unwrap().file(), file!());
    /// ```
    #[inline]
    fn location(&self) -> Option<Location> {
        None
    }

    /// The name of the error type, `"Type::Variant"` for generated types
    /// (OpenTelemetry `exception.type`). The default is the implementing
    /// type's full path.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::prelude::*;
    ///
    /// define_errors! {
    ///     pub struct Cancelled => "operation cancelled";
    /// }
    ///
    /// assert_eq!(Cancelled.type_name(), "Cancelled");
    /// ```
    #[inline]
    fn type_name(&self) -> &'static str {
        core::any::type_name::<Self>()
    }
}

/// `std::io::Error`: the category comes from the error's kind, and memory
/// exhaustion adds `Kinds::RESOURCE`.
///
/// # Examples
///
/// ```
/// use define_err::prelude::*;
///
/// let err = std::io::Error::from(std::io::ErrorKind::NotFound);
/// assert_eq!(err.category(), Category::NotFound);
/// assert_eq!(err.category().http_status(), 404);
/// ```
#[cfg(feature = "std")]
#[cfg_attr(docsrs, doc(cfg(feature = "std")))]
impl ErrorInfo for std::io::Error {
    fn category(&self) -> Category {
        Category::from_io_kind(self.kind())
    }

    fn kinds(&self) -> Kinds {
        match self.kind() {
            std::io::ErrorKind::OutOfMemory => Kinds::ERROR.union(Kinds::RESOURCE),
            _ => Kinds::ERROR,
        }
    }

    fn type_name(&self) -> &'static str {
        "std::io::Error"
    }
}

/// A catalog entry: everything known about one code.
///
/// The fields are public to read; the struct is `#[non_exhaustive]`, so
/// entries are built with [`new`](CodeInfo::new) and the `const` `with_*`
/// methods, which is what generated code does. Every type whose
/// `define_errors!` block has a namespace has `CATALOG: &'static [CodeInfo]`.
///
/// # Examples
///
/// A hand-written catalog, for codes not tied to a type:
///
/// ```
/// use define_err::{code, Category, CodeInfo};
///
/// pub const PROTOCOL: &[CodeInfo] = &[
///     CodeInfo::new(code!("PROTO", 1), "Frame too large", "Lower max_frame or raise the peer's limit.")
///         .with_category(Category::ResourceExhausted),
/// ];
///
/// assert_eq!(PROTOCOL[0].code.to_string(), "PROTO-0001");
/// assert!(PROTOCOL[0].is_active());
/// ```
#[derive(Clone, Copy, Debug)]
#[non_exhaustive]
pub struct CodeInfo {
    /// The code.
    pub code: Code,
    /// A short title; the variant name unless `title = "..."` was given.
    pub title: &'static str,
    /// What to do about it.
    pub help: &'static str,
    /// The documentation URL template, if the block has `docs = "..."`.
    pub docs: Option<&'static str>,
    /// The severity of the variant.
    pub severity: Severity,
    /// The category of the variant.
    pub category: Category,
    /// The kinds of the variant.
    pub kinds: Kinds,
    /// The action of the variant.
    pub action: Action,
    /// The public message of the variant.
    pub public: &'static str,
    /// Active, deprecated, or retired.
    pub state: CodeState,
    /// `"Type::Variant"`, or empty for a retired entry.
    pub type_name: &'static str,
}

impl CodeInfo {
    /// An entry with category `Unknown` and its defaults, kinds `ERROR`, no
    /// docs, state `Active`, and an empty type name.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::{code, Category, CodeInfo};
    ///
    /// const INFO: CodeInfo = CodeInfo::new(code!("APP", 1), "Bad input", "Fix the input.");
    /// assert_eq!(INFO.category, Category::Unknown);
    /// ```
    #[must_use]
    pub const fn new(code: Code, title: &'static str, help: &'static str) -> CodeInfo {
        CodeInfo {
            code,
            title,
            help,
            docs: None,
            severity: Category::Unknown.default_severity(),
            category: Category::Unknown,
            kinds: Kinds::ERROR,
            action: Category::Unknown.default_action(),
            public: Category::Unknown.default_public_message(),
            state: CodeState::Active,
            type_name: "",
        }
    }

    /// Sets the documentation URL template (`{code}`, `{namespace}`,
    /// `{number}` are replaced by [`url`](CodeInfo::url)).
    #[must_use]
    pub const fn with_docs(mut self, template: &'static str) -> CodeInfo {
        self.docs = Some(template);
        self
    }

    /// Sets the severity.
    #[must_use]
    pub const fn with_severity(mut self, severity: Severity) -> CodeInfo {
        self.severity = severity;
        self
    }

    /// Sets the category, and with it the severity, action, and public
    /// message defaults; set those after this call to override them.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::{code, Category, CodeInfo, Severity};
    ///
    /// const INFO: CodeInfo = CodeInfo::new(code!("APP", 1), "Lost", "Restore it.")
    ///     .with_category(Category::DataLoss);
    /// assert_eq!(INFO.severity, Severity::CRITICAL);
    /// ```
    #[must_use]
    pub const fn with_category(mut self, category: Category) -> CodeInfo {
        self.category = category;
        self.severity = category.default_severity();
        self.action = category.default_action();
        self.public = category.default_public_message();
        self
    }

    /// Sets the kinds.
    #[must_use]
    pub const fn with_kinds(mut self, kinds: Kinds) -> CodeInfo {
        self.kinds = kinds;
        self
    }

    /// Sets the action.
    #[must_use]
    pub const fn with_action(mut self, action: Action) -> CodeInfo {
        self.action = action;
        self
    }

    /// Sets the public message.
    #[must_use]
    pub const fn with_public(mut self, text: &'static str) -> CodeInfo {
        self.public = text;
        self
    }

    /// Sets the state.
    #[must_use]
    pub const fn with_state(mut self, state: CodeState) -> CodeInfo {
        self.state = state;
        self
    }

    /// Sets the type name.
    #[must_use]
    pub const fn with_type_name(mut self, name: &'static str) -> CodeInfo {
        self.type_name = name;
        self
    }

    /// The documentation URL, written without allocating; `None` when the
    /// entry has no template.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::{code, CodeInfo};
    ///
    /// const INFO: CodeInfo = CodeInfo::new(code!("DB", 1), "Timeout", "Raise pool.size.")
    ///     .with_docs("https://docs.hivedb.com/errors/{code}");
    /// assert_eq!(INFO.url().unwrap().to_string(), "https://docs.hivedb.com/errors/DB-0001");
    /// ```
    #[must_use]
    pub fn url(&self) -> Option<UrlDisplay<'_>> {
        self.docs.map(|template| UrlDisplay { template, code: self.code })
    }

    /// Whether the code is active (neither deprecated nor retired).
    #[must_use]
    pub const fn is_active(&self) -> bool {
        matches!(self.state, CodeState::Active)
    }
}

/// Whether a code is in use, deprecated, or retired.
///
/// # Examples
///
/// ```
/// use define_err::{code, CodeInfo, CodeState};
///
/// const OLD: CodeInfo = CodeInfo::new(code!("DB", 4), "OldQuota", "Use DB-0010.")
///     .with_state(CodeState::Deprecated { since: "2.1", replacement: Some(code!("DB", 10)) });
/// assert!(!OLD.is_active());
/// ```
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[non_exhaustive]
pub enum CodeState {
    /// In use.
    Active,
    /// Still works; a replacement may exist. The error service may warn when
    /// one is reported.
    Deprecated {
        /// The version the code was deprecated in.
        since: &'static str,
        /// The code to use instead.
        replacement: Option<Code>,
    },
    /// Used once and never to be reused; no variant has it.
    Retired,
}

/// A documentation URL: the template with `{code}`, `{namespace}`, and
/// `{number}` replaced. From [`CodeInfo::url`].
///
/// # Examples
///
/// ```
/// use define_err::{code, CodeInfo};
///
/// const INFO: CodeInfo = CodeInfo::new(code!("DB", 7), "Busy", "Wait.")
///     .with_docs("https://example.com/{namespace}/{number}");
/// assert_eq!(INFO.url().unwrap().to_string(), "https://example.com/DB/7");
/// ```
#[derive(Clone, Copy, Debug)]
pub struct UrlDisplay<'a> {
    template: &'a str,
    code: Code,
}

impl fmt::Display for UrlDisplay<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut rest = self.template;
        while let Some(open) = rest.find('{') {
            f.write_str(&rest[..open])?;
            let tail = &rest[open..];
            if let Some(after) = tail.strip_prefix("{code}") {
                fmt::Display::fmt(&self.code, f)?;
                rest = after;
            } else if let Some(after) = tail.strip_prefix("{namespace}") {
                f.write_str(&self.code.namespace().as_str())?;
                rest = after;
            } else if let Some(after) = tail.strip_prefix("{number}") {
                fmt::Display::fmt(&self.code.number(), f)?;
                rest = after;
            } else {
                f.write_str("{")?;
                rest = &tail[1..];
            }
        }
        f.write_str(rest)
    }
}

/// Searching and checking catalogs from several crates, without a registry.
pub mod catalog {
    use core::fmt;

    use crate::{Code, CodeInfo};

    /// The first entry with `code` in `catalogs`, searched in order.
    ///
    /// Linear in the number of entries [est. under 1 us for 1,000 codes].
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::{catalog, code, CodeInfo};
    ///
    /// const A: &[CodeInfo] = &[CodeInfo::new(code!("DB", 1), "Timeout", "Raise pool.size.")];
    /// assert_eq!(catalog::find(&[A], code!("DB", 1)).unwrap().title, "Timeout");
    /// assert!(catalog::find(&[A], code!("DB", 2)).is_none());
    /// ```
    #[must_use]
    pub fn find(catalogs: &[&'static [CodeInfo]], code: Code) -> Option<&'static CodeInfo> {
        catalogs.iter().flat_map(|entries| entries.iter()).find(|entry| entry.code == code)
    }

    /// Checks that no code appears twice across `catalogs`: the boot-time
    /// check across crates. Retired entries count as taken.
    ///
    /// Quadratic in the number of entries and allocation-free [est. under
    /// 1 ms for 1,000 codes, once at boot].
    ///
    /// # Errors
    ///
    /// [`DuplicateCode`] naming the code and the two entries' type names.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::{catalog, code, CodeInfo};
    ///
    /// const A: &[CodeInfo] = &[CodeInfo::new(code!("DB", 1), "Timeout", "x").with_type_name("DbError::Timeout")];
    /// const B: &[CodeInfo] = &[CodeInfo::new(code!("DB", 1), "Busy", "y").with_type_name("StoreError::Busy")];
    ///
    /// assert!(catalog::check_unique(&[A]).is_ok());
    /// let err = catalog::check_unique(&[A, B]).unwrap_err();
    /// assert_eq!(err.first, "DbError::Timeout");
    /// assert_eq!(err.second, "StoreError::Busy");
    /// ```
    pub fn check_unique(catalogs: &[&'static [CodeInfo]]) -> Result<(), DuplicateCode> {
        let mut entries = catalogs.iter().flat_map(|entries| entries.iter());
        while let Some(first) = entries.next() {
            if let Some(second) = entries.clone().find(|other| other.code == first.code) {
                return Err(DuplicateCode {
                    code: first.code,
                    first: first.type_name,
                    second: second.type_name,
                });
            }
        }
        Ok(())
    }

    /// Two catalog entries with the same code.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::{catalog, code, CodeInfo};
    ///
    /// const A: &[CodeInfo] = &[CodeInfo::new(code!("DB", 1), "a", "a").with_type_name("A::X")];
    /// let err = catalog::check_unique(&[A, A]).unwrap_err();
    /// assert!(err.to_string().starts_with("code DB-0001 is defined twice"));
    /// ```
    #[derive(Clone, Copy, Debug)]
    #[non_exhaustive]
    pub struct DuplicateCode {
        /// The code defined twice.
        pub code: Code,
        /// The type name of the first entry (empty for a retired entry).
        pub first: &'static str,
        /// The type name of the second entry (empty for a retired entry).
        pub second: &'static str,
    }

    impl fmt::Display for DuplicateCode {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            let name = |n: &'static str| if n.is_empty() { "a retired entry" } else { n };
            write!(
                f,
                "code {} is defined twice: by {} and by {}; give one crate its own namespace",
                self.code,
                name(self.first),
                name(self.second)
            )
        }
    }

    impl core::error::Error for DuplicateCode {}
}

#[cfg(test)]
mod tests {
    extern crate std;

    use core::fmt;
    use std::string::ToString;

    use super::{catalog, CodeInfo, CodeState, ErrorInfo};
    use crate::{Action, Category, Code, Kinds, Severity};

    #[derive(Debug)]
    struct Manual;

    impl fmt::Display for Manual {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str("manual")
        }
    }

    impl core::error::Error for Manual {}

    impl ErrorInfo for Manual {}

    fn code(n: u32) -> Code {
        crate::Namespace::try_new("DB").unwrap().code(n).unwrap()
    }

    #[test]
    fn test_error_info_defaults_for_hand_written_type() {
        assert!(Manual.code().is_none());
        assert!(Manual.code_info().is_none());
        assert_eq!(Manual.category(), Category::Unknown);
        assert_eq!(Manual.severity(), Severity::ERROR);
        assert_eq!(Manual.kinds(), Kinds::ERROR);
        assert_eq!(Manual.public_message(), "An unexpected error occurred.");
        assert!(Manual.help().is_none());
        assert_eq!(Manual.action(), Action::Operator);
        assert!(!Manual.is_retryable());
        assert!(Manual.retry_after().is_none());
        assert!(Manual.location().is_none());
        assert!(Manual.type_name().ends_with("Manual"));
    }

    #[test]
    fn test_error_info_object_safe_type_name_is_concrete() {
        let dynamic: &dyn ErrorInfo = &Manual;
        assert!(dynamic.type_name().ends_with("Manual"));
    }

    #[test]
    fn test_url_display_replaces_every_placeholder() {
        let info = CodeInfo::new(code(42), "t", "h").with_docs("x/{code}/{namespace}/{number}/{code}/{other}{");
        assert_eq!(info.url().unwrap().to_string(), "x/DB-0042/DB/42/DB-0042/{other}{");
        assert!(CodeInfo::new(code(1), "t", "h").url().is_none());
    }

    #[test]
    fn test_check_unique_cases() {
        static EMPTY: [CodeInfo; 0] = [];
        static ONE: [CodeInfo; 1] = [CodeInfo::new(
            match crate::Namespace::try_new("DB") {
                Ok(ns) => match ns.code(1) {
                    Some(c) => c,
                    None => panic!(),
                },
                Err(_) => panic!(),
            },
            "t",
            "h",
        )];
        assert!(catalog::check_unique(&[]).is_ok());
        assert!(catalog::check_unique(&[&EMPTY]).is_ok());
        assert!(catalog::check_unique(&[&ONE]).is_ok());
        let err = catalog::check_unique(&[&ONE, &ONE]).unwrap_err();
        assert_eq!(err.code, code(1));
        assert!(err.to_string().contains("a retired entry"));
    }

    #[test]
    fn test_with_category_sets_defaults() {
        let info = CodeInfo::new(code(1), "t", "h").with_category(Category::DataLoss);
        assert_eq!(info.severity, Severity::CRITICAL);
        assert_eq!(info.action, Action::PageOnCall);
        assert_eq!(info.public, "An internal error occurred.");
        assert_eq!(info.state, CodeState::Active);
    }

    #[cfg(feature = "std")]
    #[test]
    fn test_io_error_info() {
        let err = std::io::Error::from(std::io::ErrorKind::OutOfMemory);
        assert_eq!(err.category(), Category::ResourceExhausted);
        assert!(err.kinds().contains(Kinds::RESOURCE));
        assert_eq!(err.type_name(), "std::io::Error");
    }
}
